"""Generate the compact capstone report from actual result values, never from placeholders."""
import json

def report_markdown(r):
    lines=['# 微型文本与证据实验：实际运行报告','',f'> 运行时间：{r["collected_at"]}；模式：{r["mode"]}。工程核对通过，应用质量结论：{r["quality_review"]["status"]}。','', '## 1. 问题、输入与范围','', '同一CPU小项目复用经典训练方法与明确的证据链。语言任务是两字母复制/反转，资料任务是原创虚构设施的单字段问答。规则抽取和神经生成分别评价，不把前者成功当成后者能力。','', '全部训练产物位于本章独立目录；运行前后核对既有21/22检查点和报告及26/27报告未变。模型随机初始化预训练600步，另执行237步保存恢复核验，再进行800步回答区间SFT。replay模式只重新推理，不声称新训练。','', '![综合项目路线](../../../docs/assets/30-capstone/project-flow.svg)','', '## 2. 配置、来源与工作账本','', 'Python '+r['environment']['python']+'；NumPy '+r['environment']['numpy']+'；PyTorch '+r['environment']['torch']+'，CPU单线程、模型float32。语料、SFT与评估JSONL和程序均在源清单中记录SHA256。','', '![优化事件账本](../../../docs/assets/30-capstone/budget-ledger.svg)','', '文件指纹与参数指纹的用途不同；当前检查点文件如下。']
    for name,obj in r['checkpoints'].items():lines+=['',f'**{name}**：`{obj["path"]}`','', '```text',obj['file_sha256'],'```']
    lines+=['','## 3. 真实曲线与恢复','',f'预训练固定600步；SFT验证最低点为{r["training"]["sft"]["best_update"]}步。保存恢复后的参数最大绝对差为{r["training"]["resume"]["maximum_parameter_absolute_error"]}，评估历史和采样状态均相同。推理检查点重新加载logits差均为0。','', '![本章独立训练曲线](../../../docs/assets/30-capstone/training-curves.svg)','', '## 4. 固定任务评估','', '| 方法 | 既有24例正确 | 新字母12例正确 |','| --- | ---: | ---: |']
    for name,values in r['language']['summaries'].items():lines.append(f'| {name} | {values["existing_22_test"]["correct"]}/24 | {values["new_alphabet_diagnostic"]["correct"]}/12 |')
    lines+=['','既有22测试是已知测试的复评，不是新盲测。新字母诊断保持模板、改变输出范围。全部用贪心、8字节或LF停止，严格答案、格式、UTF8和停止单独记录；完整预测在results.json。','',f'检索经验证选择{r["retrieval"]["selected"]["width"]}字符、重叠{r["retrieval"]["selected"]["overlap"]}，k=3、上下文2块。规则可回答EM={r["retrieval"]["rule_result"]["answer_em"]:.0%}，未知问题拒答={r["retrieval"]["rule_result"]["abstention_accuracy"]:.0%}。','']
    for name,p in r['neural_evidence'].items():lines.append(f'- 真实{name}神经读者：无证据EM={p["closed_book_em"]:.0%}；完整证据EM={p["with_evidence_em"]:.0%}，共12题。')
    lines+=['','## 5. 回顾性应用门槛与失败','', '以下门槛为本章示例应用要求，前章结果已知，不伪称新盲测预注册；未通过的质量要求不会因为程序退出码0而变成通过。','', '![应用门槛](../../../docs/assets/30-capstone/quality-review.svg)','', '![真实失败记录](../../../docs/assets/30-capstone/failure-cases.svg)','', '## 6. 可复现交付与局限','', '![证据包结构](../../../docs/assets/30-capstone/evidence-package.svg)','', f'本次模式{r["mode"]}的工程核对数为{r["checks"]["count"]}。数值流程耗时（不含主依赖导入及图文生成导出）约{r["resources"]["current_run_seconds_excluding_imports_and_export"]:.3f}秒。数值参数负载不等于进程峰值，本章未测峰值。','', 'manifest.json或replay-manifest.json分别记录源文件与产物SHA256，artifact-verification.json逐文件复核。HTML/PDF由本文件及纯SVG同源导出，字体嵌入、矢量对象和双视口检查写入report-publication.json。','', '这份数据没有自然语言开放问答、人类偏好或自然照片验收。质量不达标时，保留失败，下一轮在开发数据验证假设并另行冻结评价，不能依此直接部署通用助手。']
    lines+=['','## 7. 方法来源','', '实验组织依据Goodfellow等《Deep Learning》第11章§11.1、§11.2、§11.5：[官方教材](https://www.deeplearningbook.org/contents/guidelines.html)。具体模型、数据、检索和指标实现复用本仓库第21、22、26、27章的已说明接口，来源文件逐项写入manifest。','', '检查点区分推理与继续训练，参见PyTorch 2.15官方[保存与加载教程](https://docs.pytorch.org/tutorials/beginner/saving_loading_models.html)；同环境确定性边界参见[Reproducibility](https://docs.pytorch.org/docs/2.15/notes/randomness.html)。']
    if not r.get('publication',{}).get('export_requested',False):
        lines=[line.replace('HTML/PDF由本文件及纯SVG同源导出，字体嵌入、矢量对象和双视口检查写入report-publication.json。','本次未执行HTML/PDF导出；目录内可能残留的旧HTML/PDF及report-publication.json不属于本次出版验收。') for line in lines]
    else:
        lines=[line.replace('HTML/PDF由本文件及纯SVG同源导出，字体嵌入、矢量对象和双视口检查写入report-publication.json。','本次请求从同一Markdown和纯SVG导出HTML/PDF；是否完成及双视口/矢量检查，以本次report-publication.json与入口退出状态为准。') for line in lines]
    return '\n'.join(lines)+'\n'
